#!/usr/bin/env node
/**
 * A15 security gate — culture image hosts ≡ CSP image allowlist (web + native), plus the
 * Phase II Permissions-Policy guard.
 *
 * Why this exists: remote culture images are the only third-party content this app draws.
 * The image hosts come from the bundled corpus (ingestion), the web CSP is generated by
 * scripts/build-headers.mjs and the Android WebView CSP by scripts/prepare-native-web.mjs.
 * Those three lists must be EXACTLY the same set: a host in the corpus but not in the CSP
 * is silently blocked (broken feature), a host in the CSP but not in the corpus is unused
 * egress permission (over-broad policy), and web/native drift breaks only one deployment.
 *
 * Contract (owned by A15, consumed by A09/A10/A11):
 *   src/lib/culture/media-hosts.json
 *     { "version": 1, "hosts": ["images.metmuseum.org", "www.artic.edu", ...] }
 *   - bare lowercase hostnames: no scheme, no path, no port, no wildcard, no leading dot.
 *   - the same file is the runtime allowlist source for culture image URLs.
 * Fallback accepted for a differently-shaped integration:
 *   src/lib/culture/media.ts  exporting  CULTURE_IMAGE_HOSTS = ["...", ...]
 *
 * Run: node tests/security/csp-image-hosts.mjs
 * Exit code 0 = pass, 1 = fail. No dependencies and no DOM: runs under plain Node.
 */
import { readFileSync, existsSync, readdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const WEB = "scripts/build-headers.mjs";
const NATIVE = "scripts/prepare-native-web.mjs";
const problems = [];
const notes = [];
const fail = (message) => problems.push(message);
const warn = (message) => notes.push(message);
const read = (relative) => readFileSync(join(ROOT, relative), "utf8");

const HOSTNAME = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
const normalizeHost = (value) => value.trim().toLowerCase().replace(/\.$/, "");

/* ------------------------------------------------------------- 1. media host registry */
function loadRegistry() {
  const jsonPath = "src/lib/culture/media-hosts.json";
  const tsPath = "src/lib/culture/media.ts";
  if (existsSync(join(ROOT, jsonPath))) {
    let parsed;
    try {
      parsed = JSON.parse(read(jsonPath));
    } catch (error) {
      fail(`${jsonPath}: not valid JSON (${error.message})`);
      return null;
    }
    const list = Array.isArray(parsed) ? parsed : parsed?.hosts;
    if (!Array.isArray(list)) {
      fail(`${jsonPath}: expected an array or { "hosts": [...] }`);
      return null;
    }
    return { source: jsonPath, hosts: list };
  }
  if (existsSync(join(ROOT, tsPath))) {
    const match = /CULTURE_IMAGE_HOSTS\s*(?::[^=]+)?=\s*\[([\s\S]*?)\]/.exec(read(tsPath));
    if (!match) {
      fail(`${tsPath}: CULTURE_IMAGE_HOSTS array literal not found`);
      return null;
    }
    const hosts = [...match[1].matchAll(/["']([^"']+)["']/g)].map((m) => m[1]);
    return { source: tsPath, hosts };
  }
  fail(
    "no culture image host registry found: add src/lib/culture/media-hosts.json with " +
      '{ "version": 1, "hosts": ["<exact origin host>", ...] } from the bundled media manifest',
  );
  return null;
}

/* ---------------------------------------------------------------- 2. CSP source parsing */
/**
 * Extract the source lists of one CSP directive from a script's source.
 *
 * The policies are written as double-quoted JS string literals (`"img-src 'self' ..."`).
 * Match the complete string literal first — a naive `/img-src([^']*)/` stops at the single
 * quote in `'self'` and silently reads an empty policy (a false-PASS gate). Then take the
 * text after the directive name and tokenize by whitespace.
 */
function directiveSourceLists(relative, directive) {
  const literal = /"(?:[^"\\]|\\.)*"/g;
  const lists = [];
  for (const match of read(relative).matchAll(literal)) {
    const value = match[0].slice(1, -1);
    const at = value.indexOf(directive);
    if (at === -1) continue;
    const rest = value.slice(at + directive.length);
    // Only a real directive ("img-src ..."), never an identifier such as "img-srcset".
    if (rest.length && !/^\s/.test(rest)) continue;
    lists.push(rest.trim().split(/\s+/).filter(Boolean));
  }
  return lists;
}

/** Every img-src directive in one script's source, as token lists (one per policy copy). */
function imgSrcDirectives(relative) {
  const directives = directiveSourceLists(relative, "img-src");
  if (!directives.length) fail(`${relative}: no img-src directive found`);
  return directives;
}

function connectSrcTokens(relative) {
  return directiveSourceLists(relative, "connect-src").flat();
}

/** https host origins in a directive; rejects wildcard/scheme-wide/http/port sources. */
function httpsHosts(relative, tokens) {
  const hosts = new Set();
  for (const token of tokens) {
    if (token === "*" || token === "https:" || token === "http:" || token.startsWith("http://")) {
      fail(
        `${relative} img-src: forbidden CSP source "${token}" (no wildcard or scheme-wide http(s))`,
      );
      continue;
    }
    if (token.includes("*")) {
      fail(`${relative} img-src: wildcard source "${token}" is not allowed for third-party media`);
      continue;
    }
    if (!token.startsWith("https://")) continue; // 'self', data:, blob:
    let url;
    try {
      url = new URL(token);
    } catch {
      fail(`${relative} img-src: "${token}" is not a valid origin`);
      continue;
    }
    if (url.pathname !== "/" || url.search || url.hash || url.username || url.password) {
      fail(`${relative} img-src: "${token}" must be a bare origin, not a URL`);
      continue;
    }
    if (url.port && url.port !== "443") {
      fail(`${relative} img-src: non-default port in "${token}"`);
      continue;
    }
    if (!HOSTNAME.test(url.hostname) || url.hostname.startsWith(".")) {
      fail(`${relative} img-src: invalid hostname in "${token}"`);
      continue;
    }
    hosts.add(url.hostname.toLowerCase());
  }
  return hosts;
}

/* --------------------------------------------------------------------- 3. comparisons */
function onlyIn(a, b) {
  return [...a].filter((value) => !b.has(value)).sort();
}

function compareSets(label, a, b) {
  const onlyA = onlyIn(a, b);
  const onlyB = onlyIn(b, a);
  if (!onlyA.length && !onlyB.length) return;
  fail(
    `${label} disagree: missing [${onlyA.join(", ") || "-"}], extra [${onlyB.join(", ") || "-"}]`,
  );
}

/* --------------------------------------------------------------------- run the checks */
for (const relative of [WEB, NATIVE]) {
  if (!existsSync(join(ROOT, relative))) fail(`${relative}: missing (cannot verify its CSP)`);
}

const registry = loadRegistry();
const registryHosts = new Set();
if (registry) {
  const seen = new Set();
  for (const raw of registry.hosts) {
    if (typeof raw !== "string") {
      fail(`${registry.source}: non-string entry ${JSON.stringify(raw)}`);
      continue;
    }
    const host = normalizeHost(raw);
    if (host !== raw) fail(`${registry.source}: host "${raw}" must be the normalized "${host}"`);
    if (!HOSTNAME.test(host) || host.startsWith(".")) {
      fail(`${registry.source}: "${raw}" is not a bare hostname (no scheme/path/port/wildcard)`);
      continue;
    }
    if (seen.has(host)) fail(`${registry.source}: duplicate host "${host}"`);
    seen.add(host);
    registryHosts.add(host);
  }
}

const webHosts = new Set();
const nativeHosts = new Set();
if (existsSync(join(ROOT, WEB))) {
  for (const tokens of imgSrcDirectives(WEB)) {
    for (const host of httpsHosts(WEB, tokens)) webHosts.add(host);
  }
}
if (existsSync(join(ROOT, NATIVE))) {
  for (const tokens of imgSrcDirectives(NATIVE)) {
    for (const host of httpsHosts(NATIVE, tokens)) nativeHosts.add(host);
  }
}

if (registry) {
  compareSets(`${WEB} img-src vs ${registry.source}`, registryHosts, webHosts);
  compareSets(`${NATIVE} img-src vs ${registry.source}`, registryHosts, nativeHosts);
  compareSets(`${WEB} vs ${NATIVE} image hosts`, webHosts, nativeHosts);
  // Drawing a third-party image is not fetch egress: never list an image host in connect-src.
  for (const [relative, files] of [
    [WEB, [WEB]],
    [NATIVE, [NATIVE]],
  ]) {
    void files;
    for (const token of connectSrcTokens(relative)) {
      if (!token.startsWith("https://")) continue;
      try {
        const host = new URL(token).hostname.toLowerCase();
        if (registryHosts.has(host)) {
          fail(`${relative} connect-src contains image host "${host}" (no fetch egress needed)`);
        }
      } catch {
        /* other sources are checked by the img-src pass where they matter */
      }
    }
  }
}

/* ------------------------------------------- 4. corpus consistency (when the data landed) */
const dataDir = join(ROOT, "src/lib/culture/data");
let corpusFiles = 0;
let mediaUrls = 0;
const corpusHosts = new Set();
if (existsSync(dataDir)) {
  for (const name of readdirSync(dataDir)) {
    if (!name.endsWith(".ts")) continue;
    corpusFiles += 1;
    const text = read(join("src/lib/culture/data", name));
    for (const block of text.matchAll(/"?media"?\s*:\s*\{[\s\S]*?\}/g)) {
      for (const urlMatch of block[0].matchAll(
        /(?:^|[,{\s])(?:url|thumbnailUrl)\s*:\s*"([^"]+)"/g,
      )) {
        mediaUrls += 1;
        let parsed;
        try {
          parsed = new URL(urlMatch[1]);
        } catch {
          fail(`src/lib/culture/data/${name}: media URL is not absolute: ${urlMatch[1]}`);
          continue;
        }
        if (parsed.protocol !== "https:") {
          fail(`src/lib/culture/data/${name}: media URL must be https: ${urlMatch[1]}`);
          continue;
        }
        corpusHosts.add(parsed.hostname.toLowerCase());
        if (registry && !registryHosts.has(parsed.hostname.toLowerCase())) {
          fail(
            `src/lib/culture/data/${name}: media host "${parsed.hostname}" is not in ${registry.source} ` +
              "(the image would be blocked; add it to the registry and both CSP files)",
          );
        }
      }
    }
  }
  if (!corpusFiles) warn("src/lib/culture/data exists but holds no .ts modules");
  else if (!mediaUrls) warn("culture corpus has no media URLs in media blocks");
} else {
  warn("src/lib/culture/data not generated yet: corpus→registry consistency is NOT_VERIFIED");
}

/* ------------------------------------------------------------ 5. Phase II header guards */
if (existsSync(join(ROOT, WEB))) {
  const headerScript = read(WEB);
  if (!/geolocation=\(self\)/.test(headerScript)) {
    fail(`${WEB}: Permissions-Policy must allow geolocation for this origin (geolocation=(self))`);
  }
  if (/geolocation=\(\)/.test(headerScript)) {
    fail(`${WEB}: geolocation=() disables the Geolocation API for self too`);
  }
}

/* ------------------------------------------------------------------------------ report */
console.log(
  `  · registry: ${registry ? `${registry.source} (${registryHosts.size} host${registryHosts.size === 1 ? "" : "s"})` : "MISSING"}`,
);
console.log(`  · web img-src hosts: ${webHosts.size} → ${[...webHosts].sort().join(", ") || "-"}`);
console.log(
  `  · native img-src hosts: ${nativeHosts.size} → ${[...nativeHosts].sort().join(", ") || "-"}`,
);
console.log(
  `  · corpus: ${corpusFiles} module(s), ${mediaUrls} media URL(s), ${corpusHosts.size} host(s)`,
);
for (const message of notes) console.log(`SKIP/NOTE: ${message}`);
if (problems.length) {
  for (const message of problems) console.error(`FAIL: ${message}`);
  console.error(`\n${problems.length} problem(s) — the culture image allowlist is not consistent.`);
  process.exitCode = 1;
} else {
  console.log(
    "PASS: culture image hosts are identical in the registry, the web CSP and the native CSP" +
      (mediaUrls ? ` (${mediaUrls} corpus media URLs)` : ""),
  );
}
